script:
// Visuals come from style / size / enabled; instance background, corner, border, shadow and clip land on the
// invisible 44pt hit-area root and do not restyle the circle.
// IconButton (ds-metrics §2 — CircularIconButton): circle 44 (large) / 40 (small) with a 22 / 20 icon, tint el16,
// disabled iconDisabled (DS global icons.disabled2), inside a tappable root of at least 44 × 44. style: solid =
// solidChromeSurface, glass = GlassButtonBackground: a `glass` layer under the icon with the regular material (a real
// blur on iOS, a translucent bg1 fill on Android) and glassButtonBackground over it; outline = el3 hairline, plain = no
// surface. The DS has no press visual here. `label` is the a11y label (the button has no text).
param icon: icon
param label: string = ""
param size: "large" | "small" = "large"
param style: "solid" | "glass" | "outline" | "plain" = "solid"
param enabled: bool = true
event tap
let box = size == "small" ? 40 : 44
